import assert from 'node:assert/strict';
import { transpose } from '../matrix.js';
test('rectangle', () => assert.deepEqual(transpose([[1, 2, 3], [4, 5, 6]]), [[1, 4], [2, 5], [3, 6]]));
test('square', () => assert.deepEqual(transpose([[1, 2], [3, 4]]), [[1, 3], [2, 4]]));
